 "content": "from collections import Counter


def transform(grid):
    """Overlay sparse marks in the upper panel onto background cells below."""
    sep = next((i for i, row in enumerate(grid) if row and len(set(row)) == 1), None)
    if sep is None:
        raise ValueError("separator row not found")
    top, bottom = grid[:sep], grid[sep + 1:]
    if len(top) != len(bottom):
        raise ValueError("panels must have matching heights")
    h, w = len(top), len(top[0])
    top_bg = Counter(v for row in top for v in row).most_common(1)[0][0]
    bottom_bg = Counter(v for row in bottom for v in row).most_common(1)[0][0]
    out = [[5 for _ in range(w)] for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if top[r][c] != top_bg and bottom[r][c] == bottom_bg:
                out[r][c] = 3
    return out
